import java.util.*;
import java.io.*;

public class Main {
    static class Fraction {
        long numerator, denominator;
        Fraction(long numerator, long denominator) {
            this.numerator = numerator;
            this.denominator = denominator;
        }
    }

    static long[] getBounds(int x, int y, int b) {
        long low = (long) b * x / y;
        long high = ((long) b * x + y - 1) / y;
        return new long[]{low, high};
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static void process(int x, int y, int n, PrintWriter out) {
        List<Fraction> candidates = new ArrayList<>();
        for (int b = 1; b <= n; b++) {
            long[] bounds = getBounds(x, y, b);
            candidates.add(new Fraction(bounds[0], b));
            candidates.add(new Fraction(bounds[1], b));
        }

        candidates.sort((f1, f2) -> {
            long a1 = f1.numerator, b1 = f1.denominator;
            long a2 = f2.numerator, b2 = f2.denominator;
            long diff1 = Math.abs((long) x * b1 * b2 - a1 * b2 * y);
            long diff2 = Math.abs((long) x * b1 * b2 - a2 * b1 * y);
            if (diff1 != diff2) return Long.compare(diff1, diff2);
            if (b1 != b2) return Long.compare(b1, b2);
            return Long.compare(a1, a2);
        });

        Fraction result = candidates.get(0);
        out.println(result.numerator + "/" + result.denominator);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int x = sc.nextInt();
        int y = sc.nextInt();
        int n = sc.nextInt();
        process(x, y, n, out);
        out.flush();
        sc.close();
    }
}
